class Widget {};

// Scenario 1: Preferred method using make_shared (single allocation)
// The control block and the Widget object are allocated together.
auto spw1 = std::make_shared<Widget>();

// Scenario 2: Less efficient method (two allocations)
// First allocation for the Widget, second for the control block.
Widget* pWidget = new Widget();
std::shared_ptr<Widget> spw2(pWidget);

// Scenario 3: DANGEROUS - Undefined Behavior
// Creates two independent control blocks for the same raw pointer.
// Both spw3 and spw4 will try to delete pWidget2 when they are destroyed.
Widget* pWidget2 = new Widget();
std::shared_ptr<Widget> spw3(pWidget2);
